import openpyxl
from openpyxl.utils import get_column_letter
path='/root/data/workbook.xlsx'
wb=openpyxl.load_workbook(path, data_only=False)
print('Sheet names:', wb.sheetnames)
for s in ['Task','Data']:
    print(f"Has sheet {s}?", s in wb.sheetnames)
wsT=wb['Task']
wsD=wb['Data']

# Task sheet years row 10 columns H-L
years={}
for col in range(8,13):
    cell=f"{get_column_letter(col)}10"
    years[cell]=wsT[cell].value
print('\nTask!H10:L10 (years headers):')
for k,v in years.items():
    print(k,repr(v))

# series codes in column D rows 12-17, 19-24, 26-31
blocks=[(12,17,'Inbound? block rows 12-17'),(19,24,'Outbound? block rows 19-24'),(26,31,'Capacity? block rows 26-31')]
print('\nTask column D series codes:')
for r1,r2,label in blocks:
    print(label)
    for r in range(r1,r2+1):
        print(f" D{r}: {wsT[f'D{r}'].value!r}")

# port names rows 35-40 column D
print('\nTask ports (D35:D40):')
for r in range(35,41):
    print(f" D{r}: {wsT[f'D{r}'].value!r}")

# row 50 label
row50={}
for col in range(1,13):
    cell=f"{get_column_letter(col)}50"
    val=wsT[cell].value
    if val is not None:
        row50[cell]=val
print('\nTask row 50 non-empty cells:')
for k in sorted(row50.keys()):
    print(k, row50[k])

# stats labels rows 42-47 col D/E/F/G
print('\nTask stats labels rows 42-47 columns D-G:')
for r in range(42,48):
    vals=[]
    for c in range(4,8):
        cell=f"{get_column_letter(c)}{r}"
        vals.append((cell,wsT[cell].value))
    print(r, vals)

# Data layout inspect rows 21-38, columns A-Z maybe
print('\nData!21:38 snapshot (A:Z) with coordinates for non-empty):')
for r in range(21,39):
    row=[]
    for c in range(1,27):
        v=wsD.cell(r,c).value
        if v is not None and v!='':
            row.append((get_column_letter(c)+str(r),v))
    if row:
        print(r, row[:20], '...' if len(row)>20 else '')

# Heuristics to find year header row: look for row with many ints/years in range 1900-2100
from collections import defaultdict
candidate_rows=[]
for r in range(21,39):
    years_in_row=[]
    for c in range(1,51):
        v=wsD.cell(r,c).value
        if isinstance(v,(int,float)) and 1900<=int(v)<=2100 and abs(v-int(v))<1e-9:
            years_in_row.append((c,int(v)))
        elif isinstance(v,str) and v.isdigit() and 1900<=int(v)<=2100:
            years_in_row.append((c,int(v)))
    if len(years_in_row)>=3:
        candidate_rows.append((r,years_in_row))
print('\nCandidate year-header rows in Data 21-38:')
for r,yrs in candidate_rows:
    print('Row',r,'years',yrs[:12], 'count',len(yrs))

# Candidate series code column: look for column with many non-empty strings in these rows
candidate_cols=[]
for c in range(1,51):
    vals=[]
    for r in range(21,39):
        v=wsD.cell(r,c).value
        if isinstance(v,str) and v.strip()!='':
            vals.append((r,v.strip()))
    if len(vals)>=10:
        candidate_cols.append((c,vals))
print('\nCandidate series-code columns in Data 21-38 (>=10 strings):')
for c,vals in candidate_cols[:10]:
    print('Col',get_column_letter(c),'sample',vals[:8],'count',len(vals))

